@RestController
@RequestMapping("/emps")
public class EmpController {

    private static final Logger log = LoggerFactory.getLogger(EmpController.class);

    @Autowired
    private EmpService empService;

    /**
     * GET /emps - 条件分页查询员工
     * @param name     姓名 (模糊)
     * @param gender   性别
     * @param begin    入职日期起始
     * @param end      入职日期截止
     * @param page     页码 (默认1)
